static void inorder(struct TreeNode *root, int *res, int *size) {
  if (!root) {
    return;
  }
  inorder(root->left, res, size);
  res[(*size)++] = root->val;
  inorder(root->right, res, size);
}

int *inorderTraversal(struct TreeNode *root, int *returnSize) {
  int *res = (int *)malloc(sizeof(int) * 100);
  *returnSize = 0;
  inorder(root, res, returnSize);
  return res;
}

class Solution {
public:
  void inorder(TreeNode *root, vector<int> &res) {
    if (!root) {
      return;
    }
    inorder(root->left, res);
    res.push_back(root->val);
    inorder(root->right, res);
  }
  vector<int> inorderTraversal(TreeNode *root) {
    vector<int> res;
    inorder(root, res);
    return res;
  }
};

func inorderTraversal(root *TreeNode) []int {
	var res []int
	var inorder func(node *TreeNode)
	inorder = func(node *TreeNode) {
		if node == nil {
			return
		}
		inorder(node.Left)
		res = append(res, node.Val)
		inorder(node.Right)
	}
	inorder(root)
	return res
}

class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class Solution {
  public List<Integer> inorderTraversal(TreeNode root) {
    List<Integer> res = new ArrayList<>();
    inorder(root, res);
    return res;
  }

  private void inorder(TreeNode root, List<Integer> res) {
    if (root == null) {
      return;
    }
    inorder(root.left, res);
    res.add(root.val);
    inorder(root.right, res);
  }
}

class Solution:
    def inorderTraversal(self, root: Optional[TreeNode]) -> List[int]:
        res = []

        def inorder(node: Optional[TreeNode]):
            if node is None:
                return
            inorder(node.left)
            res.append(node.val)
            inorder(node.right)

        inorder(root)
        return res

impl Solution {
  pub fn inorder_traversal(root: Option<Box<TreeNode>>) -> Vec<i32> {
    fn inorder(node: &Option<Box<TreeNode>>, res: &mut Vec<i32>) {
      if let Some(n) = node {
        inorder(&n.left, res);
        res.push(n.val);
        inorder(&n.right, res);
      }
    }
    let mut res = vec![];
    inorder(&root, &mut res);
    res
  }
}

const inorderTraversal = (root: TreeNode | null): number[] => {
  const res: number[] = [];
  const inorder = (node: TreeNode | null) => {
    if (!node) return;
    inorder(node.left);
    res.push(node.val);
    inorder(node.right);
  };
  inorder(root);
  return res;
};
